{
  "findings": [
    {
      "check_id": "CKV2_AWS_22",
      "title": "Ensure an IAM User does not have access to the console",
      "resource": "aws_iam_user.fp3-deny-iam-user",
      "severity": "MEDIUM",
      "explanation": "The IAM user 'fp3-deny-iam-user' is created without explicitly disabling console access, potentially allowing console login."
    }
  ],
  "patched_code": "resource \"aws_iam_user\" \"fp3-deny-iam-user\" {\n  name          = \"fp3-deny-iam-user\"\n  path          = \"/\"\n  force_destroy = true\n}\nresource \"aws_iam_user_login_profile\" \"fp3-deny-iam-user\" {\n  user    = aws_iam_user.fp3-deny-iam-user.name\n  pgp_key = \"keybase:somekeybaseusername\"\n}\nresource \"aws_iam_access_key\" \"fp3-deny-iam-user\" {\n  user = aws_iam_user.fp3-deny-iam-user.name\n  pgp_key = \"keybase:somekeybaseusername\"\n}",
  "fix_summary": "Added resources to securely manage the IAM user's credentials and prevent console access by using pgp_key for access key and login profile"
}
